/** Route context shared by the router and both server adapters. */
export interface Request {
  method: string
  path: string
  params: Record<string, string>
  query: Record<string, string>
  headers: Headers
  raw: globalThis.Request
  state: Map<string, unknown>
}

/** Decoded query values, with the last value winning for repeated keys. */
export type Query = Record<string, string>

export type Handler = (request: Request) => Response | Promise<Response>
export type Next = () => Promise<Response>
export type Middleware = (request: Request, next: Next) => Response | Promise<Response>
export type ErrorHandler = (error: unknown, request: Request) => Response | Promise<Response>

export interface RouterOptions {
  /** Treat /users and /users/ as different routes. Defaults to false. */
  strictSlash?: boolean
  onError?: ErrorHandler
}

export interface RouteInfo {
  method: string
  path: string
}

/** An expected HTTP failure whose message is safe to send to a client. */
export class HttpError extends Error {
  readonly status: number
  readonly headers: Headers

  constructor(status: number, message: string, headers?: HeadersInit) {
    super(message)
    this.name = "HttpError"
    this.status = status
    this.headers = new Headers(headers)
  }
}

export function errorResponse(error: unknown): Response {
  if (error instanceof HttpError) {
    return Response.json({ error: error.message }, {
      status: error.status,
      headers: error.headers,
    })
  }
  return Response.json({ error: "Internal server error" }, { status: 500 })
}

import type { Query } from "./types.ts"

/** Decode form-style query components, including + as a space. */
const decode = (value: string): string => decodeURIComponent(value.replace(/\+/g, " "))

/** Parse a query string. Repeated keys keep their last value. */
export function parseQuery(input: string): Query {
  const params: Record<string, string> = {}
  const query = input.startsWith("?") ? input.slice(1) : input
  for (const pair of query.split("&")) {
    if (pair === "") continue
    const eq = pair.indexOf("=")
    if (eq === -1 || eq === pair.length - 1) continue
    const key = decode(pair.slice(0, eq))
    Object.defineProperty(params, key, {
      value: decode(pair.slice(eq + 1)),
      enumerable: true,
      configurable: true,
      writable: true,
    })
  }
  return params
}

/** Serialize a plain record as a query string without a leading ?. */
export function buildQuery(params: Query): string {
  return Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&")
}

import { parseQuery } from "./query.ts"
import { errorResponse, HttpError } from "./errors.ts"
import type { Handler, Middleware, Request, RouteInfo, RouterOptions } from "./types.ts"

export type { Handler, Middleware, Request } from "./types.ts"

interface Route extends RouteInfo {
  segments: string[]
  handler: Handler
  score: number
}

const split = (path: string): string[] => path.split("/").filter(part => part !== "")

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment)
  } catch {
    throw new HttpError(400, "Invalid percent encoding in path")
  }
}

/** Match the path shape first, then decode named segments.
 * Static segments remain literal, so an encoded slash cannot add a segment.
 * Undefined means this route is not a candidate for the requested path.
 */
function match(route: Route, parts: string[]): Record<string, string> | undefined {
  if (route.segments.length !== parts.length) return undefined
  const params: Record<string, string> = {}
  for (let i = 0; i < parts.length; i += 1) {
    const segment = route.segments[i]!
    const value = parts[i]!
    if (segment.startsWith(":")) {
      params[segment.slice(1)] = decodeSegment(value)
    } else if (segment !== value) {
      return undefined
    }
  }
  return params
}

/** A small HTTP router with explicit middleware order and Web Response handlers. */
export class Router {
  private routes: Route[] = []
  private middleware: Middleware[] = []
  private options: RouterOptions

  constructor(options: RouterOptions = {}) {
    this.options = options
  }

  /** Run middleware in registration order around the selected handler. */
  use(middleware: Middleware): this {
    this.middleware.push(middleware)
    return this
  }

  /** Register a GET handler and return this router. */
  get(path: string, handler: Handler): this {
    return this.add("GET", path, handler)
  }

  /** Register a POST handler and return this router. */
  post(path: string, handler: Handler): this {
    return this.add("POST", path, handler)
  }

  /** Register a PUT handler and return this router. */
  put(path: string, handler: Handler): this {
    return this.add("PUT", path, handler)
  }

  /** Register a PATCH handler and return this router. */
  patch(path: string, handler: Handler): this {
    return this.add("PATCH", path, handler)
  }

  /** Register a DELETE handler and return this router. */
  delete(path: string, handler: Handler): this {
    return this.add("DELETE", path, handler)
  }

  /** Register a OPTIONS handler and return this router. */
  optionsFor(path: string, handler: Handler): this {
    return this.add("OPTIONS", path, handler)
  }

  /** Return public route metadata without exposing handlers. */
  inspect(): RouteInfo[] {
    return this.routes.map(({ method, path }) => ({ method, path }))
  }

  private add(method: string, path: string, handler: Handler): this {
    if (!path.startsWith("/")) throw new TypeError("Route paths must start with /")
    const segments = split(path)
    const names = segments.filter(part => part.startsWith(":"))
    if (names.some(name => name.length === 1)) throw new TypeError("A route parameter needs a name")
    if (new Set(names).size !== names.length) throw new TypeError("Route parameters must be unique")
    // More literal segments make a route more specific.
    // Stable sorting keeps registration order when two routes have equal scores.
    const score = segments.filter(part => !part.startsWith(":")).length
    this.routes.push({ method, path, segments, handler, score })
    this.routes.sort((a, b) => b.score - a.score)
    return this
  }

  /** Accept method + relative URL, or use fetch() for a native Request. */
  async handle(method: string, url: string, init: RequestInit = {}): Promise<Response> {
    const target = new URL(url, "http://localhost")
    return this.fetch(new globalThis.Request(target, { ...init, method }))
  }

  /** The server adapters share this entry point. */
  async fetch(raw: globalThis.Request): Promise<Response> {
    const url = new URL(raw.url)
    // Normalizing the method leaves adapter behavior identical across runtimes.
    const method = raw.method.toUpperCase()
    const parts = split(url.pathname)
    const request: Request = {
      method,
      path: url.pathname,
      params: {},
      query: {},
      headers: raw.headers,
      raw,
      state: new Map(),
    }
    try {
      request.query = parseQuery(url.search)
      let selected: Route | undefined
      const allowed = new Set<string>()
      for (const route of this.routes) {
        if (this.options.strictSlash && route.path.endsWith("/") !== url.pathname.endsWith("/")) continue
        const params = match(route, parts)
        if (!params) continue
        allowed.add(route.method)
        if (route.method === "GET") allowed.add("HEAD")
        if (route.method !== method && !(method === "HEAD" && route.method === "GET")) continue
        if (selected && method === "HEAD" && route.method !== "HEAD") continue
        selected = route
        request.params = params
        if (method !== "HEAD" || route.method === "HEAD") break
      }
      // Matching a path with another method is distinct from a missing path.
      // This also allows middleware to wrap the router-generated 404 and 405.
      const terminal: Handler = selected
        ? selected.handler
        : () => allowed.size
          ? new Response("Method not allowed", {
            status: 405,
            headers: { Allow: [...allowed].sort().join(", ") },
          })
          : new Response("Not found", { status: 404 })
      // HEAD runs the same middleware and handler before dropping the body.
      const response = await this.dispatch(request, terminal)
      return method === "HEAD"
        ? new Response(null, { status: response.status, headers: response.headers })
        : response
    } catch (error) {
      if (this.options.onError) return this.options.onError(error, request)
      if (error instanceof URIError) return errorResponse(new HttpError(400, "Invalid query encoding"))
      return errorResponse(error)
    }
  }

  private async dispatch(request: Request, handler: Handler): Promise<Response> {
    // Keep a single cursor per request to detect duplicate next() calls.
    // Each request gets its own cursor, including concurrent fetch calls.
    let previous = -1
    const invoke = async (index: number): Promise<Response> => {
      if (index <= previous) throw new Error("next() called more than once")
      previous = index
      const middleware = this.middleware[index]
      if (!middleware) return handler(request)
      return middleware(request, () => invoke(index + 1))
    }
    return invoke(0)
  }
}

import type { Middleware } from "../types.ts"

export interface CorsOptions {
  origin?: string | string[]
  methods?: string[]
  headers?: string[]
  credentials?: boolean
  maxAge?: number
}

/** Add CORS headers and answer browser preflight requests. */
export function cors(options: CorsOptions = {}): Middleware {
  const origins = options.origin ?? "*"
  const methods = options.methods ?? ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]
  return async (request, next) => {
    const incoming = request.headers.get("origin")
    const origin = typeof origins === "string"
      ? origins
      : incoming && origins.includes(incoming) ? incoming : ""
    const preflight = request.method === "OPTIONS" && request.headers.has("access-control-request-method")
    const response = preflight ? new Response(null, { status: 204 }) : await next()
    const headers = new Headers(response.headers)
    if (origin) headers.set("access-control-allow-origin", origin)
    if (origins !== "*") headers.append("vary", "Origin")
    if (options.credentials) headers.set("access-control-allow-credentials", "true")
    if (preflight) {
      headers.set("access-control-allow-methods", methods.join(", "))
      headers.set("access-control-allow-headers", (options.headers ?? ["content-type"]).join(", "))
      headers.set("access-control-max-age", String(options.maxAge ?? 600))
    }
    return new Response(response.body, { status: response.status, headers })
  }
}

import type { Middleware } from "../types.ts"

export interface LogRecord {
  method: string
  path: string
  status: number
  durationMs: number
}

/** Log a completed response; query strings and request bodies stay private. */
export function logger(write: (record: LogRecord) => void = console.info): Middleware {
  return async (request, next) => {
    const start = performance.now()
    const response = await next()
    write({
      method: request.method,
      path: request.path,
      status: response.status,
      durationMs: Math.round((performance.now() - start) * 100) / 100,
    })
    return response
  }
}

import { HttpError } from "../errors.ts"
import type { Middleware, Request } from "../types.ts"

const key = "tinyhttp.body"

/** Read a size-limited JSON body once and store it on the request context. */
export function jsonBody(maxBytes = 1024 * 1024): Middleware {
  return async (request, next) => {
    if (!request.headers.get("content-type")?.split(";")[0]?.trim().endsWith("/json")) return next()
    if (Number(request.headers.get("content-length")) > maxBytes) throw new HttpError(413, "Body too large")
    const reader = request.raw.body?.getReader()
    if (!reader) throw new HttpError(400, "Expected a JSON body")
    const chunks: Uint8Array[] = []
    let size = 0
    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        size += value.byteLength
        if (size > maxBytes) {
          await reader.cancel()
          throw new HttpError(413, "Body too large")
        }
        chunks.push(value)
      }
    } finally {
      reader.releaseLock()
    }
    const bytes = new Uint8Array(size)
    let offset = 0
    for (const chunk of chunks) {
      bytes.set(chunk, offset)
      offset += chunk.byteLength
    }
    try {
      request.state.set(key, JSON.parse(new TextDecoder().decode(bytes)))
    } catch {
      throw new HttpError(400, "Invalid JSON")
    }
    return next()
  }
}

export function body<T = unknown>(request: Request): T {
  return request.state.get(key) as T
}

import type { Router } from "../router.ts"

export interface BunOptions {
  port?: number
  hostname?: string
}

/** Start Bun's HTTP server with the same Web Request used by tests. */
export function serve(router: Router, options: BunOptions = {}) {
  return Bun.serve({
    port: options.port ?? 3000,
    hostname: options.hostname ?? "127.0.0.1",
    fetch: (request: globalThis.Request) => router.fetch(request),
  })
}

import { createServer, type IncomingMessage, type ServerResponse } from "node:http"
import { Readable } from "node:stream"
import { finished } from "node:stream/promises"
import type { Router } from "../router.ts"

export function toRequest(incoming: IncomingMessage): globalThis.Request {
  const headers = new Headers()
  for (const [key, value] of Object.entries(incoming.headers)) {
    if (Array.isArray(value)) value.forEach(item => headers.append(key, item))
    else if (value !== undefined) headers.set(key, value)
  }
  const method = incoming.method ?? "GET"
  const init: RequestInit & { duplex?: "half" } = { method, headers }
  if (method !== "GET" && method !== "HEAD") {
    init.body = Readable.toWeb(incoming) as unknown as BodyInit
    init.duplex = "half"
  }
  const path = incoming.url?.startsWith("/") ? incoming.url : "/"
  return new globalThis.Request(new URL(path, "http://localhost"), init)
}

async function send(response: Response, outgoing: ServerResponse): Promise<void> {
  outgoing.statusCode = response.status
  response.headers.forEach((value, key) => outgoing.setHeader(key, value))
  if (!response.body) { outgoing.end(); return }
  const body = Readable.fromWeb(response.body as unknown as import("node:stream/web").ReadableStream)
  body.pipe(outgoing)
  await finished(outgoing)
}

/** Return an unbound server so the caller controls its port and shutdown. */
export function createNodeServer(router: Router) {
  return createServer((incoming, outgoing) => {
    router.fetch(toRequest(incoming)).then(response => send(response, outgoing)).catch(() => {
      if (!outgoing.headersSent) outgoing.writeHead(500, { "content-type": "text/plain" })
      outgoing.end("Internal server error")
    })
  })
}

import { expect, test } from "bun:test"
import { Router } from "../src/router.ts"

test("matches params and decodes values", async () => {
  const app = new Router().get("/users/:id", req => Response.json(req.params))
  expect(await (await app.handle("GET", "/users/a%20b")).json()).toEqual({ id: "a b" })
})

test("static routes win regardless of registration order", async () => {
  const app = new Router().get("/users/:id", () => new Response("param"))
  app.get("/users/me", () => new Response("static"))
  expect(await (await app.handle("GET", "/users/me")).text()).toBe("static")
})

test("unmatched paths return 404", async () => {
  expect((await new Router().handle("GET", "/missing")).status).toBe(404)
})

test("other methods return 405 and Allow", async () => {
  const app = new Router().get("/users", () => new Response("ok"))
  const response = await app.handle("POST", "/users")
  expect(response.status).toBe(405)
  expect(response.headers.get("allow")).toBe("GET, HEAD")
})

test("HEAD keeps headers and drops the response body", async () => {
  const app = new Router().get("/status", () => new Response("healthy", { headers: { "x-ready": "1" } }))
  const response = await app.handle("HEAD", "/status")
  expect(response.headers.get("x-ready")).toBe("1")
  expect(await response.text()).toBe("")
})

test("malformed path encoding is a client error", async () => {
  const app = new Router().get("/users/:id", () => new Response("ok"))
  expect((await app.handle("GET", "/users/%ZZ")).status).toBe(400)
})

test("middleware wraps the handler in registration order", async () => {
  const calls: string[] = []
  const app = new Router().use(async (_, next) => {
    calls.push("before")
    const response = await next()
    calls.push("after")
    return response
  }).get("/", () => { calls.push("handler"); return new Response("ok") })
  await app.handle("GET", "/")
  expect(calls).toEqual(["before", "handler", "after"])
})

test("rejects unnamed and repeated route parameters", () => {
  const app = new Router()
  expect(() => app.get("/:", () => new Response())).toThrow("needs a name")
  expect(() => app.get("/:id/:id", () => new Response())).toThrow("must be unique")
})

