import { expect, test } from "bun:test"
import type { AddressInfo } from "node:net"
import { Router } from "../src/router.ts"
import { createNodeServer } from "../src/adapters/node.ts"

async function withServer(app: Router, read: (url: string) => Promise<void>) {
  const server = createNodeServer(app)
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve))
  try { await read(`http://127.0.0.1:${(server.address() as AddressInfo).port}`) }
  finally { await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve())) }
}

test("streams a Web Response through Node", async () => {
  await withServer(new Router().get("/", () => new Response("node")), async url => {
    expect(await (await fetch(url)).text()).toBe("node")
  })
})

test("forwards request bodies", async () => {
  await withServer(new Router().post("/", async req => new Response(await req.raw.text())), async url => {
    expect(await (await fetch(url, { method: "POST", body: "hello" })).text()).toBe("hello")
  })
})

