import { expect, test } from "bun:test"
import type { Handler, Middleware, Request } from "../src/types.ts"

test("middleware and handlers share the route context", async () => {
  const request: Request = { method: "GET", path: "/", params: {}, query: {}, headers: new Headers(), raw: new globalThis.Request("http://localhost/"), state: new Map() }
  const handler: Handler = req => Response.json({ method: req.method })
  const middleware: Middleware = async (req, next) => { req.state.set("visited", true); return next() }
